var projects = build.FindChildrenRecursive<Project>();
foreach (var p in projects)
{
    Console.WriteLine($"\n=== Project: {p.Name} ===");
    var items = p.FindChildrenRecursive<Item>();
    foreach (var item in items)
    {
        if (item.Name == "Compile" || item.Name == "SourceFile")
            Console.WriteLine($"  Compile: {item.Text}");
    }

    // Look for CscCommandLineArgs or compiler invocations
    var tasks = p.FindChildrenRecursive<Task>();
    foreach (var t in tasks)
    {
        if (t.Name == "Csc")
        {
            Console.WriteLine($"  CSC task found");
            var cmdLine = t.FindChildrenRecursive<Property>();
            foreach (var prop in cmdLine.Take(20))
            {
                Console.WriteLine($"    {prop.Name} = {prop.Value}");
            }
        }
    }
}
EOF
