using System.Linq;
using Microsoft.Build.Logging.StructuredLogger;

var build = BinaryLog.ReadBuild(args[0]);

// Check all errors with full detail
var errors = build.FindChildrenRecursive<Error>();
Console.WriteLine("=== ALL ERRORS ===");
foreach (var e in errors)
{
    var proj = e.GetNearestParent<Project>();
    Console.WriteLine($"Project: {proj?.Name ?? "unknown"}");
    Console.WriteLine($"  File: {e.File}");
    Console.WriteLine($"  Line: {e.LineNumber}, Col: {e.ColumnNumber}");
    Console.WriteLine($"  Code: {e.Code}");
    Console.WriteLine($"  Message: {e.Text}");
    Console.WriteLine();
}

// Check which projects failed and why
Console.WriteLine("=== PROJECT BUILD ORDER & STATUS ===");
var projects = build.FindChildrenRecursive<Project>();
foreach (var p in projects.Where(p => p.Name.EndsWith(".csproj")))
{
    var hasErrors = p.FindChildrenRecursive<Error>().Any();
    var hasOwnErrors = p.FindChildrenRecursive<Error>().Where(e => !e.Text.Contains("dependency")).Any();
    Console.WriteLine($"{p.Name}: {(hasErrors ? "FAILED" : "OK")}");
}
EOF
